/* Basic reset and full screen canvas styling */
html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    overflow: hidden;
    background-color: #000;
    color: #fff;
    font-family: Arial, sans-serif;
    user-select: none;
}

#gameCanvas {
    display: block;
    background-color: #222;
    margin: 0 auto;
    touch-action: none;
}
